<template><div class="dashboard"><div class="intro"><div><div class="eyebrow">QINGHE CAMPUS · BUSINESS OVERVIEW</div><h1>{{platform?'校园好味道，从这里开始。':'今天，也要认真做好每一餐。'}}</h1><p>{{platform?'总后台 · 连接校园里的每一份美味':'商家工作台 · 这里是你专属的经营空间'}} <span> / {{today}}</span></p></div><el-button @click="load">刷新数据</el-button></div><div class="hero"><div><div class="hero-label">每一餐，都是一份信任</div><h2>好好经营，好好生活。</h2><p>及时接单、用心备餐，让新顾客成为老朋友。</p><el-button @click="$router.push('/food/orders')">查看待处理订单 →</el-button></div><div class="hero-art">禾<span>青禾校园</span></div></div><div class="metrics"><div v-for="m in metrics" :key="m.label" class="metric"><div class="metric-label">{{m.label}} <span>{{m.icon}}</span></div><div class="metric-value">{{m.value}}</div><div class="metric-sub">{{m.sub}}</div></div></div><div class="chart-grid"><el-card shadow="never"><template #header><div class="card-title">近7天经营趋势 <span>成交金额（元）</span></div></template><div ref="chartEl" style="height:290px"/></el-card><el-card shadow="never"><template #header><div class="card-title">人气菜品 <span>累计销量</span></div></template><div v-for="(p,i) in data.popular||[]" :key="p.name" class="popular"><span class="rank">{{String(i+1).padStart(2,'0')}}</span><div class="popular-name">{{p.name}}<div>可售库存 {{p.stock}}</div></div><strong>{{p.sales}}</strong></div></el-card></div><div class="quick-links"><el-button @click="$router.push('/food/products')">管理菜品 →</el-button><el-button @click="$router.push('/food/stores')">{{platform?'管理商家':'店铺设置'}} →</el-button><span>数据来自当前账号可访问的店铺</span></div></div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';import * as echarts from 'echarts';import {foodGet,money} from '@/api/food';const data=ref({today:{}}),platform=ref(false),chartEl=ref();let chart;const today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});const metrics=computed(()=>[{label:'今日成交金额',value:'¥ '+money(data.value.today.revenue),sub:'已支付订单金额',icon:'↗'},{label:'今日订单',value:data.value.today.orders||0,sub:'包含未支付和已取消',icon:'▤'},{label:'待接单',value:data.value.today.pending||0,sub:'请及时处理新订单',icon:'◷'},{label:platform.value?'平台用户':'本店顾客',value:data.value.members||0,sub:'营业店铺 '+(data.value.stores||0)+' 家',icon:'♧'}]);async function load(){const [r,s]=await Promise.all([foodGet('/overview'),foodGet('/scope')]);data.value=r.data;platform.value=s.data.platform;await nextTick();chart ||= echarts.init(chartEl.value);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`});chart.setOption({grid:{top:15,bottom:30,left:50,right:20},tooltip:{trigger:'axis'},xAxis:{type:'category',data:days.map(d=>d.slice(5)),axisLine:{lineStyle:{color:'#e2e8dc'}},axisLabel:{color:'#9ca791'}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf1e8',type:'dashed'}},axisLabel:{color:'#9ca791'}},series:[{data:days.map(d=>Number(data.value.trend?.find(t=>String(t.day).slice(0,10)===d)?.revenue||0)/100),type:'line',smooth:true,symbolSize:7,lineStyle:{width:3,color:'#759774'},itemStyle:{color:'#759774'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#b7cda777'},{offset:1,color:'#b7cda705'}])}}]})}function resize(){chart?.resize()}onMounted(()=>{load();window.addEventListener('resize',resize)});onBeforeUnmount(()=>{chart?.dispose();window.removeEventListener('resize',resize)});
</script>
<style scoped>.dashboard{padding:32px;background:#f6f8f3;min-height:calc(100vh - 85px);color:#335039}.intro{display:flex;align-items:center;justify-content:space-between;margin-bottom:25px}.eyebrow{font-size:10px;letter-spacing:2px;color:#90a080}h1{font-size:27px;margin:13px 0}p{font-size:13px;color:#92a087}p span{color:#a3ad99;margin-left:10px}.hero{background:linear-gradient(110deg,#e2ead3,#f0eed9);border-radius:18px;padding:33px 40px;display:flex;justify-content:space-between;align-items:center;margin-bottom:25px;overflow:hidden}.hero-label{font-size:12px;letter-spacing:3px;color:#98a17b}.hero h2{font-size:30px;margin:16px 0}.hero p{color:#8a9775}.hero button{background:#f7f9ee;border:0;color:#5f7a4e;margin-top:8px}.hero-art{width:160px;height:160px;display:flex;align-items:center;justify-content:center;flex-direction:column;border:1px solid #acbc9260;border-radius:50%;font-size:70px;color:#8d9c6c;transform:rotate(-10deg);outline:18px solid #b7c6a115;margin-right:20px}.hero-art span{font-size:12px;letter-spacing:5px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-bottom:24px}.metric{padding:24px;background:white;border:1px solid #e8eddf;border-radius:14px}.metric-label{font-size:13px;color:#86947d;display:flex;justify-content:space-between}.metric-label span{font-size:20px;color:#9aab8b}.metric-value{font-size:31px;margin:18px 0;font-weight:700;letter-spacing:1px}.metric-sub{font-size:11px;color:#a4ad9c}.chart-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:24px}.el-card{border-radius:15px;border-color:#e8eddf}.card-title{font-size:15px;font-weight:600}.card-title span{float:right;font-size:11px;color:#a0ab95;font-weight:400}.popular{display:flex;gap:18px;align-items:center;padding:16px 0;border-bottom:1px solid #f0f3ec}.rank{color:#afb89c;font-size:16px}.popular-name{font-size:13px;flex:1}.popular-name div{font-size:11px;color:#a7af9e;margin-top:7px}.popular strong{font-size:16px;color:#788f63}.quick-links{display:flex;align-items:center;margin-top:22px;gap:12px}.quick-links span{margin-left:auto;font-size:11px;color:#a8b09e}@media(max-width:1100px){.metrics{grid-template-columns:repeat(2,1fr)}.chart-grid{grid-template-columns:1fr}.hero-art{display:none}}</style>
